-- Master data (module "masterdata", UC-01/UC-02).
--
-- Conventions (docs/domain-model.md, ADR-0004):
--   * every table carries tenant_id (BPNL of the tenant); business keys are unique per tenant
--   * id = UUIDv7 generated by the application, version = optimistic lock (exposed as ETag)
--   * created_at/by, updated_at/by maintained by the application (JPA auditing)
--   * references between aggregates use the business key where the key is stable and exchanged with partners
--     (partner BPNL, site BPNS) and the technical id otherwise (part, relation); key changes of referenced
--     objects are rejected by the application (REFERENCED)
-- TODO(ADR-0004): PostgreSQL row-level security on tenant_id as second line of defence.

CREATE TABLE md_part
(
    id               UUID                     NOT NULL,
    tenant_id        VARCHAR(16)              NOT NULL,
    version          BIGINT                   NOT NULL,
    created_at       TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by       VARCHAR(255)             NOT NULL,
    updated_at       TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_by       VARCHAR(255)             NOT NULL,
    part_number      VARCHAR(64)              NOT NULL,
    name_de          VARCHAR(255)             NOT NULL,
    name_en          VARCHAR(255),
    drawing_number   VARCHAR(64),
    drawing_revision VARCHAR(64),
    material         VARCHAR(255),
    catena_x_id      VARCHAR(64),
    active           BOOLEAN                  NOT NULL,
    CONSTRAINT pk_md_part PRIMARY KEY (id),
    CONSTRAINT uq_md_part_number UNIQUE (tenant_id, part_number)
);

-- roles: sorted, comma-separated set of CUSTOMER/SUPPLIER. A two-value enum set that is always read and written
-- with the partner and never queried by itself does not justify a join table.
CREATE TABLE md_partner
(
    id            UUID                     NOT NULL,
    tenant_id     VARCHAR(16)              NOT NULL,
    version       BIGINT                   NOT NULL,
    created_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by    VARCHAR(255)             NOT NULL,
    updated_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_by    VARCHAR(255)             NOT NULL,
    bpnl          VARCHAR(16)              NOT NULL,
    name          VARCHAR(255)             NOT NULL,
    roles         VARCHAR(32)              NOT NULL,
    dsp_endpoint  VARCHAR(2048),
    did           VARCHAR(2048),
    contact_email VARCHAR(254),
    active        BOOLEAN                  NOT NULL,
    CONSTRAINT pk_md_partner PRIMARY KEY (id),
    CONSTRAINT uq_md_partner_bpnl UNIQUE (tenant_id, bpnl),
    CONSTRAINT ck_md_partner_roles CHECK (roles IN ('CUSTOMER', 'SUPPLIER', 'CUSTOMER,SUPPLIER'))
);

-- owner_bpnl: own tenant or a partner (validated by the application; no FK because the tenant is not a partner).
CREATE TABLE md_site
(
    id          UUID                     NOT NULL,
    tenant_id   VARCHAR(16)              NOT NULL,
    version     BIGINT                   NOT NULL,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by  VARCHAR(255)             NOT NULL,
    updated_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_by  VARCHAR(255)             NOT NULL,
    bpns        VARCHAR(16)              NOT NULL,
    name        VARCHAR(255)             NOT NULL,
    owner_bpnl  VARCHAR(16)              NOT NULL,
    street      VARCHAR(255),
    postal_code VARCHAR(64),
    city        VARCHAR(255),
    country     VARCHAR(2),
    active      BOOLEAN                  NOT NULL,
    CONSTRAINT pk_md_site PRIMARY KEY (id),
    CONSTRAINT uq_md_site_bpns UNIQUE (tenant_id, bpns)
);
CREATE INDEX ix_md_site_owner ON md_site (tenant_id, owner_bpnl);

CREATE TABLE md_relation
(
    id             UUID                     NOT NULL,
    tenant_id      VARCHAR(16)              NOT NULL,
    version        BIGINT                   NOT NULL,
    created_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by     VARCHAR(255)             NOT NULL,
    updated_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_by     VARCHAR(255)             NOT NULL,
    partner_bpnl   VARCHAR(16)              NOT NULL,
    partner_role   VARCHAR(16)              NOT NULL,
    exchange_mode  VARCHAR(32)              NOT NULL,
    policy_profile VARCHAR(64)              NOT NULL,
    active         BOOLEAN                  NOT NULL,
    CONSTRAINT pk_md_relation PRIMARY KEY (id),
    CONSTRAINT uq_md_relation_partner_role UNIQUE (tenant_id, partner_bpnl, partner_role),
    CONSTRAINT fk_md_relation_partner FOREIGN KEY (tenant_id, partner_bpnl) REFERENCES md_partner (tenant_id, bpnl),
    CONSTRAINT ck_md_relation_role CHECK (partner_role IN ('CUSTOMER', 'SUPPLIER')),
    CONSTRAINT ck_md_relation_mode CHECK (exchange_mode IN ('PUSH', 'PULL', 'PUSH_NOTIFY_PULL_PAYLOAD'))
);

CREATE TABLE md_part_mapping
(
    id                  UUID                     NOT NULL,
    tenant_id           VARCHAR(16)              NOT NULL,
    version             BIGINT                   NOT NULL,
    created_at          TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by          VARCHAR(255)             NOT NULL,
    updated_at          TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_by          VARCHAR(255)             NOT NULL,
    relation_id         UUID                     NOT NULL,
    part_id             UUID                     NOT NULL,
    partner_part_number VARCHAR(64)              NOT NULL,
    own_site_bpns       VARCHAR(16),
    partner_site_bpns   VARCHAR(16),
    CONSTRAINT pk_md_part_mapping PRIMARY KEY (id),
    CONSTRAINT uq_md_part_mapping_part UNIQUE (tenant_id, relation_id, part_id),
    CONSTRAINT uq_md_part_mapping_partner_number UNIQUE (tenant_id, relation_id, partner_part_number),
    CONSTRAINT fk_md_part_mapping_relation FOREIGN KEY (relation_id) REFERENCES md_relation (id),
    CONSTRAINT fk_md_part_mapping_part FOREIGN KEY (part_id) REFERENCES md_part (id)
);
CREATE INDEX ix_md_part_mapping_part ON md_part_mapping (part_id);

-- value_schema: JSON Schema (draft 2020-12) for structured values; JSONB because it is a document by nature.
CREATE TABLE md_catalog_element
(
    id             UUID                     NOT NULL,
    tenant_id      VARCHAR(16)              NOT NULL,
    version        BIGINT                   NOT NULL,
    created_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by     VARCHAR(255)             NOT NULL,
    updated_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_by     VARCHAR(255)             NOT NULL,
    code           VARCHAR(32)              NOT NULL,
    name_de        VARCHAR(255)             NOT NULL,
    name_en        VARCHAR(255)             NOT NULL,
    description_de VARCHAR(4000),
    description_en VARCHAR(4000),
    reference_vda  VARCHAR(255),
    reference_aiag VARCHAR(255),
    evidence_type  VARCHAR(32)              NOT NULL,
    value_schema   JSONB,
    sort_order     INTEGER                  NOT NULL,
    active         BOOLEAN                  NOT NULL,
    CONSTRAINT pk_md_catalog_element PRIMARY KEY (id),
    CONSTRAINT uq_md_catalog_element_code UNIQUE (tenant_id, code),
    CONSTRAINT ck_md_catalog_element_evidence CHECK (evidence_type IN ('DOCUMENT', 'VALUES', 'DOCUMENT_AND_VALUES'))
);

-- requirements: JSONB object {elementCode: REQUIRED|ON_REQUEST}. The matrix is always read and replaced as a whole
-- (PUT replaces it completely), it is keyed by the stable element code that is also exchanged with partners
-- (AK-02-5) and copied into requests as a snapshot; a join table would add joins without any query benefit.
-- Unknown codes are rejected by the application.
CREATE TABLE md_submission_level
(
    id             UUID                     NOT NULL,
    tenant_id      VARCHAR(16)              NOT NULL,
    version        BIGINT                   NOT NULL,
    created_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by     VARCHAR(255)             NOT NULL,
    updated_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_by     VARCHAR(255)             NOT NULL,
    code           VARCHAR(32)              NOT NULL,
    name_de        VARCHAR(255)             NOT NULL,
    name_en        VARCHAR(255)             NOT NULL,
    description_de VARCHAR(4000),
    description_en VARCHAR(4000),
    scheme         VARCHAR(16)              NOT NULL,
    sort_order     INTEGER                  NOT NULL,
    requirements   JSONB                    NOT NULL DEFAULT '{}'::jsonb,
    active         BOOLEAN                  NOT NULL,
    CONSTRAINT pk_md_submission_level PRIMARY KEY (id),
    CONSTRAINT uq_md_submission_level_code UNIQUE (tenant_id, code),
    CONSTRAINT ck_md_submission_level_scheme CHECK (scheme IN ('VDA', 'AIAG', 'CUSTOM')),
    CONSTRAINT ck_md_submission_level_requirements CHECK (jsonb_typeof(requirements) = 'object')
);

CREATE TABLE md_submission_reason
(
    id             UUID                     NOT NULL,
    tenant_id      VARCHAR(16)              NOT NULL,
    version        BIGINT                   NOT NULL,
    created_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by     VARCHAR(255)             NOT NULL,
    updated_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_by     VARCHAR(255)             NOT NULL,
    code           VARCHAR(32)              NOT NULL,
    name_de        VARCHAR(255)             NOT NULL,
    name_en        VARCHAR(255)             NOT NULL,
    description_de VARCHAR(4000),
    description_en VARCHAR(4000),
    sort_order     INTEGER                  NOT NULL,
    active         BOOLEAN                  NOT NULL,
    CONSTRAINT pk_md_submission_reason PRIMARY KEY (id),
    CONSTRAINT uq_md_submission_reason_code UNIQUE (tenant_id, code)
);
